package edu.klh.soa.shelfstock; import jakarta.persistence.*; @Entity @Table(name="shelf_stock") public class ShelfStock {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String shelfId; @Column(nullable=false) public String lotCode; @Column(nullable=false) public int quantity; @Column(nullable=false) public String status="AVAILABLE"; protected ShelfStock(){} public ShelfStock(String s,String l,int q){shelfId=s;lotCode=l;quantity=q;}}